// 临时健全性验证脚本（验证后删除）
import {
  startServer,
  launchBrowser,
  openApp,
  createTicket,
  openDetail,
  installAssignGate,
  submitAssignment,
  waitForButtonWaiting,
  editAssignee,
  getInputValue,
  getDetail,
  getListRow,
} from "./helpers.js";

const server = await startServer();
const browser = await launchBrowser();
try {
  const ticket = await createTicket(server.base);
  console.log("ticket:", ticket.id);
  const page = await openApp(browser, server.base);
  const gate = installAssignGate(page);
  await gate.enable();
  await openDetail(page, ticket.id);

  gate.hold();
  await submitAssignment(page, "  王芳  ");
  await waitForButtonWaiting(page);
  await gate.waitForPending(1);
  console.log("held request body:", JSON.stringify(gate.heldAt(0)));

  await editAssignee(page, "  李强  ");
  console.log("input while waiting:", JSON.stringify(await getInputValue(page)));
  await gate.release();

  await page.waitForFunction(
    () => {
      const n = document.getElementById("assign-notice");
      return n && n.classList.contains("ok");
    },
    { timeout: 5000 },
  );
  console.log("notice:", JSON.stringify((await getDetail(page)).fields["负责人"]));
  console.log("input after resolve:", JSON.stringify(await getInputValue(page)));
  const detail = await getDetail(page);
  console.log("detail assignee:", detail.fields["负责人"]);
  console.log("detail updated:", detail.fields["最近处理时间"]);
  console.log("history:", detail.history);
  console.log("list row:", JSON.stringify(await getListRow(page, ticket.id)));
  const t = await fetch(`${server.base}/api/tickets`).then((r) => r.json());
  const api = t.tickets.find((x) => x.id === ticket.id);
  console.log("api assignee:", api.assignee, "changed records:", api.assignments.length, "updated:", api.updatedAt);
  console.log("button:", JSON.stringify(await page.$eval("#assign-btn", (b) => ({ d: b.disabled, t: b.textContent.trim() }))));
} finally {
  await browser.close();
  await server.stop();
}

