  assert.match(notice.text, /HTTP 500/);
  assert.match(notice.text, /尚未提交/);
  assert.ok(!notice.text.includes("赵六"), "草稿名字不应被当作失败的分派对象");

  // 草稿（含首尾空白）保留。
