  const { detail } = await assertDataUnchanged(ticket.id, "王芳", updatedAt0, 1);
  assert.deepEqual(detail.history, [`未分派 → 王芳 ${fmtMinute(updatedAt0)}`]);

  await assertNoAssignmentSoon(gate, "转交失败后");
});

