// 分派失败后的隔离与可恢复性回归测试。
//
// 关注点：
//  1. 收到保存失败响应（HTTP 500）或无法连接服务时，此前提交的分派绝不能被提示成成功。
//  2. 提示要区分：失败的是“此前提交的负责人”，输入框里只是尚未提交的内容。
//  3. 等待期间后来填写或清空的输入按返回时当前内容原样保留；按钮恢复可用。
//  4. 列表与详情中的负责人、最近处理时间、分派记录不能根据失败结果改写。
//  5. 不自动重试：重试只能由用户主动点击发起；未成功的操作标识沿用，可修正后重试。
import { test, before, after, beforeEach, afterEach } from "node:test";
import assert from "node:assert/strict";
import {
  startServer,
  launchBrowser,
  openApp,
  createTicket,
  getTicket,
  assignViaApi,
  openDetail,
  reloadApp,
  installAssignGate,
  submitAssignment,
  editAssignee,
  clearAssignee,
  waitForButtonWaiting,
  waitForButtonIdle,
  waitForNoticeKind,
  getNotice,
  getInputValue,
  getDetail,
  getListRow,
  clickAssign,
  assertNoAssignmentSoon,
  fmtMinute,
} from "./helpers.js";

let server;
let browser;

before(async () => {
  server = await startServer();
  browser = await launchBrowser();
});

after(async () => {
  await browser.close();
  await server.stop();
});

let page;
let gate;

beforeEach(async () => {
  page = await openApp(browser, server.base);
  gate = installAssignGate(page);
  await gate.enable();
});

afterEach(async () => {
  gate.releaseAll();
  await page.close();
});

async function prepare() {
  const ticket = await createTicket(server.base);
  await reloadApp(page);
  await openDetail(page, ticket.id);
  gate.hold();
  return ticket;
}

// 失败后数据层面不应发生任何分派：接口、详情、列表三处一致保持旧状态。
